let oracleFixture:Promise<{expected:artifact.ProgramArtifact;database:Awaited<ReturnType<typeof owner.programSnapshotToSqliteDatabase>>;bytes:Uint8Array}>|undefined;
function completeOracleFixture(){return oracleFixture??=(async()=>{const expected=await completeFixture(),database=await owner.programSnapshotToSqliteDatabase(expected),bytes=await exportSqliteDatabase(database);return{expected,database,bytes}})()}
for(const sql of laws.malformedSql)test("Architect malformed independent SQL refuses: "+sql,async()=>{const{bytes}=await completeOracleFixture(),db=Database.deserialize(bytes);try{db.exec("PRAGMA ignore_check_constraints=ON");db.exec(sql);await expect(owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).rejects.toThrow()}finally{db.close()}});
for(const raw of laws.binary64Words)test("Architect independent SQL preserves exact IEEE word "+raw,async()=>{const{bytes}=await completeOracleFixture(),db=Database.deserialize(bytes);try{const bits=BigInt("0x"+raw),view=new DataView(new ArrayBuffer(8));view.setBigUint64(0,bits);const value=view.getFloat64(0),kind=Number.isNaN(value)?"nan":value===Infinity?"positiveInfinity":value===-Infinity?"negativeInfinity":"finite";db.run("UPDATE architect_benchmark_record SET value=?,value_ieee754_bits=?,value_ieee754_class=?",[Number.isNaN(value)?null:value,BigInt.asIntN(64,bits),kind]);const restored=await owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()));expect(restored.benchmarksPayload[0]!.value.bits).toBe(bits);const rewritten=Database.deserialize(await exportSqliteDatabase(await owner.programSnapshotToSqliteDatabase(restored)));try{expect(rewritten.query("SELECT printf('%016llx',value_ieee754_bits) AS word,value_ieee754_class AS kind FROM architect_benchmark_record").get()).toEqual({word:raw,kind});expect((await owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(rewritten.serialize()))).benchmarksPayload[0]!.value.bits).toBe(bits)}finally{rewritten.close()}}finally{db.close()}});

test("Architect consistent structural surrogate renumbering retains logical state",async()=>{const{expected,database}=await completeOracleFixture();const tables=database.tables.map(table=>({...table,rows:table.rows.map(row=>({rowid:row.rowid,values:[...row.values]}))}));const header=tables.find(table=>table.name==="architect_entity_header")!.rows.find(row=>row.values[2]==="stakeholders")!,old=header.rowid,next=900000n;header.rowid=next;header.values[0]=next;tables.find(table=>table.name==="architect_stakeholder")!.rows.find(row=>row.rowid===old)!.rowid=next;tables.find(table=>table.name==="architect_stakeholder")!.rows.find(row=>row.rowid===next)!.values[0]=next;for(const table of tables.filter(table=>table.name==="architect_entity_consultant"||table.name==="architect_entity_participant"||table.name==="architect_entity_tag"||table.name==="architect_entity_note"||table.name.startsWith("architect_stakeholder_")))for(const row of table.rows)if(row.values[1]===old)row.values[1]=next;for(const table of tables)table.rows.sort((a,b)=>a.rowid<b.rowid?-1:a.rowid>b.rowid?1:0);const oracle=Database.deserialize(await exportSqliteDatabase({tables}));try{expect(oracle.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(await owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(oracle.serialize()))).toEqual(expected)}finally{oracle.close()}});


test("Architect actual row frontier precedes owned projection and reconstruction",async()=>{const{expected,database}=await completeOracleFixture(),count=database.tables.reduce((sum,table)=>sum+table.rows.length,0);await expect(owner.programSnapshotToSqliteDatabase(expected,{maxRows:count})).resolves.toEqual(database);await expect(owner.programSnapshotToSqliteDatabase(expected,{maxRows:count-1})).rejects.toThrow();await expect(owner.programSnapshotFromSqliteDatabase(database,{maxRows:count-1})).rejects.toThrow()});
test("Architect actual schema frontier agrees with independent SQLite text byte accounting",async()=>{const{expected,database,bytes}=await completeOracleFixture(),db=Database.deserialize(bytes);let size:number;try{size=(db.query("SELECT sum(length(CAST(name AS BLOB))+length(CAST(sql AS BLOB))) AS bytes FROM sqlite_schema WHERE type='table'").get() as{bytes:number}).bytes}finally{db.close()}for(const offset of laws.schemaLimitOffsets){const maximum=size+Number(offset[0]);if(offset[1])await expect(owner.programSnapshotToSqliteDatabase(expected,{maxSchemaBytes:maximum})).resolves.toEqual(database);else await expect(owner.programSnapshotToSqliteDatabase(expected,{maxSchemaBytes:maximum})).rejects.toThrow()}});
for(const phase of["projectSnapshot","reconstructSnapshot"] as const)test("Architect interior cancellation during "+phase,async()=>{const{expected,database}=await completeOracleFixture(),abort=new AbortController(),options={signal:abort.signal,onProgress:(event:{phase:string;completed:number})=>{if(event.phase===phase&&event.completed>0)abort.abort()}};if(phase==="projectSnapshot")await expect(owner.programSnapshotToSqliteDatabase(expected,options)).rejects.toThrow();else await expect(owner.programSnapshotFromSqliteDatabase(database,options)).rejects.toThrow()});

test("Architect every authored double position remains independently queryable with exact NaN words",async()=>{const{expected}=await completeOracleFixture(),input=structuredClone(expected),bits=0xfff0000000000123n;for(const[slot,field]of laws.binary64Fields)(input as unknown as Record<string,Record<string,unknown>[]>)[slot!]![0]![field!]={bits};const database=await owner.programSnapshotToSqliteDatabase(input),db=Database.deserialize(await exportSqliteDatabase(database));try{for(const[,field,table,column]of laws.binary64Fields){expect(db.query("SELECT "+column+" AS query,printf('%016llx',"+column+"_ieee754_bits) AS word,"+column+"_ieee754_class AS kind FROM "+table).get()).toEqual({query:null,word:"fff0000000000123",kind:"nan"})}expect(await owner.programSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input)}finally{db.close()}});

